const LIST=[R_hub,R_r1,R_r2,R_r3,R_r4,R_r5,R_a1,R_a2,R_a3,R_a4,R_a5,R_b1,R_b2,R_b3,R_b4,R_b5,R_b6,R_b7,R_m1,R_m2,R_m3,R_m4,R_m5,R_m6,R_m7,R_m8,R_m9,R_m10,R_m11,R_f1,R_f2,R_b10];
/* rooms:end */

export const ORDER=LIST.map(r=>r.id);
export const AMB={hub:1,roots:.4,flood:.45,molten:.35};   /* Molten is darker: the lava crest, the embers and his own light carry it */
export const ROOMS={};

export function parse(src){
  const R={id:src.id,name:src.name,biome:src.biome,at:src.at.slice(),w:src.grid[0].length,h:src.grid.length,
    g:src.grid.slice(),spawns:[],torches:[],plates:[],gates:[],items:[],pedestals:[],perches:[],vents:[],start:null};
  const ent=(tx,ty)=>(src.ents||[]).find(e=>e.at[0]===tx&&e.at[1]===ty)||{};
  R.g.forEach((row,ty)=>[...row].forEach((c,tx)=>{
    const e=ent(tx,ty);
    if(c==='M'||c==='O'||c==='H'||c==='E'||c==='K'||(c==='~'&&e.fish))R.spawns.push({k:c==='~'?'C':c,tx,ty,...e,at:undefined});   /* H hermit crab; a clownfish is an ent on water; E ember sprite, K slag beetle (game/cinders.js) */
    else if(c==='V')R.vents.push({tx,ty,...e,at:undefined});   /* a geyser vent on a floor: height, period, phase, live (game/geysers.js) */
    else if(c==='T')R.torches.push({tx,ty});
    else if(c==='P')R.plates.push({tx,ty});
    else if(c==='G')R.gates.push({tx,ty});
    else if(c==='I')R.items.push({tx,ty,id:e.item||'root'});
    else if(c==='B')R.perches.push({tx,ty,lookx:e.lookx||0,looky:e.looky||0});   /* a seat: stand still on it and he sits, the camera drifts toward its look */
    else if(c==='S')R.start={tx,ty};
    else if(c==='F')R.pedestals.push({tx,ty,piece:src.biome});   /* holds its biome's fragment */
  }));
  R.flows=(src.ents||[]).filter(e=>e.flow).map(e=>({at:e.at.slice(),flow:e.flow}));   /* currents (game/liquid.js) */
  /* seals: rubble (=) with ent opens:<biome> is solid until that biome's fragment is set in the door (engine solid(),
     sealOpen()). 'tx,ty' -> that biome; null when the room has none */
  R.seals=null;for(const e of src.ents||[])if(typeof e.opens==='string'&&(src.grid[e.at[1]]||'')[e.at[0]]==='=')(R.seals||(R.seals={}))[e.at[0]+','+e.at[1]]=e.opens
  return R;
}
for(const r of LIST)ROOMS[r.id]=parse(r);

/* the seat under his feet (a perch tile in his cell), or undefined */
export const perchOf=(R,p)=>{const tx=Math.floor((p.x+p.w/2)/12),ty=Math.floor((p.y+p.h-1)/12);return R.perches.find(q=>q.tx===tx&&q.ty===ty)};

/* the room whose region holds world tile (wx,wy) */
export function roomAtTile(wx,wy){
  for(const id of ORDER){const R=ROOMS[id];if(wx>=R.at[0]&&wy>=R.at[1]&&wx<R.at[0]+R.w&&wy<R.at[1]+R.h)return R}
  return null;
}

/* Chases (game/chases.js). Lifting a biome's fragment wakes its chase: a wall of thorns, its front a vertical line at a
   world x, sweeping east (dir:-1 sweeps west, and every rule below mirrors). path: [world tile x, px per frame from there on], ending in a bare [x], the safe line; he
   outruns it by crossing that. It waits `beat` frames at `from` (world tile x) before it moves. After a death it
   restarts `gap` px behind the torch he respawns at (never behind `from`); `at` can pin a torch's restart point
   ('room:tx,ty': world tile x). Assist slows it to 70% and widens the gap by half. */
export const CHASES={
  /* from the shrine (r5) through the Root Cathedral, down Deep Roots, across Spore Gate and through Puff Drift's pits; safe
     once he reaches Mossy Hush (Puff Drift's east border, x -234). The wall's speed changes by stretch (px/frame, ~4.7
     tiles/s is .95): the descent of Deep Roots zigzags back west on every left ledge, so the sweep must crawl there (.2), and
     the pits of Puff Drift cost a puff wait each, so the wall is quicker there once he is ahead. A clean run takes about 31 s;
     a bot that hesitates 1 s in every room, or respawns at any torch on the path, still clears it (tools/test_game.mjs).
     The torch on Deep Roots' mid ledge sends him back west, toward the thorns, so its restart is pinned 32 tiles behind it
     inside the Cathedral; the top torch restarts at the Cathedral's west end so the long zigzag below it starts with room to spare */
  roots:{from:-408,beat:60,gap:150,path:[[-408,.95],[-378,.85],[-342,.2],[-318,.8],[-282,.9],[-234]],at:{'r4:20,16':-354,'r4:4,5':-378}},
  /* Flood (game/tide.js): dir -1, west. From the eel's lair at the foot of Eel Grotto (b10), up its steps and back through
     Hermit Cove (f2) and Shallows (f1); safe at Shallows' west door (x 253), so Undertow's calm follows. For its 2 s beat the
     tide swells over the lair's rim; then the eel's snout (S.chase.x) moves. tide: y0 the level it swells from, rise its px
     per frame toward lv (by stretch: world tile x, world px y), drain its px per frame once outrun, lip how far the water
     runs ahead of the snout, edge and drop the curve of its leading edge, reach how high over the water the eel strikes.
     Each level is a shallow sheet 8 px over the floor where the snout is, so the water climbs Eel Grotto's steps behind
     him, and his middle stays dry on any floor ahead of it (a step is never a trap); deep only over pools and pits. The eel
     (px/frame) climbs the grotto at 1.3 and runs the cove and Shallows at 1.5 (his run is 1.6, a surf 2.8); a death restarts
     it 300 px (about 3 s) east of his torch. With the board a clean bot run takes about 20 s, closest 3 s behind him; a bot
     that waits 1 s in every room, or restarts at any torch on the way, still clears it; with the root alone it is about 27 s
     and the eel comes within 1 s (tools/test_flood_chase.mjs) */
  flood:{dir:-1,from:440,beat:120,gap:300,path:[[440,1.3],[378,1.5],[312,1.5],[253]],
    tide:{y0:448,rise:.5,drain:1,lip:120,edge:24,drop:40,reach:60,lv:[[440,412],[422,388],[416,364],[406,328],[384,304],[378,280],[312,278]]}},
  /* Molten (game/geysers.js), kind 'geyser': no front that kills, but waves of eruptions. From the pedestal at the west end
     of Geyser Core (m11, world x -164) east through the core and the vent field of Cinder Hush (m10); safe once past its
     last vent, at world x -92, before the seat, so the hush's calm half follows (R18). It only wakes when the molten
     pedestal is lifted. The first wave starts at `from` (world tile x) after `beat` frames and runs along `path` ([world
     tile x, px per clock frame], ending in the bare safe x) at 3 px/frame (he runs 1.6, so each wave overtakes him); a new
     wave every `every` frames. A vent in the span cracks and steams for `tel` frames, then erupts for `erupt`. After a death
     the first wave restarts `gap` px behind his torch. Assist: the clock runs at 70% and the telegraph is 1.5 times as long
     (clock frames). Timings in tools/test_molten.mjs */
  molten:{kind:'geyser',dir:1,from:-164,beat:60,every:180,tel:48,erupt:54,gap:150,path:[[-164,3],[-92]]},
};
